import type { InsightArticle } from "~/features/core-pages/insights-data";

export type SilverstoneBlogLink = {
  href: string;
  label: string;
};

export type SilverstoneBlogFaq = {
  answer: string;
  question: string;
};

export type SilverstoneBlogBullet = {
  body: string;
  icon?: string;
  label: string;
};

export type SilverstoneBlogGridItem = {
  body: string;
  label?: string;
  title: string;
};

export type SilverstoneBlogTable = {
  columns: string[];
  /**
   * Heading for the row-label column. Optional because every table written
   * before this existed relies on the "Decision point" default, which is what
   * those articles already render. A table converted from a markdown source
   * carries its own first-column heading here so the meaning is not lost.
   */
  rowHeader?: string;
  rows: {
    cells: string[];
    label: string;
  }[];
};

/*
 * Search-led presentation blocks.
 *
 * The `search_led_general_ai` stream writes articles whose bodies vary by
 * presentation family (ranking, comparison, cost/ROI, prompt guide, strategy,
 * troubleshooting, governance, …). The four original block types — bullets,
 * grid, comparisonTable, pullQuote — could not express a ranked provider card
 * or a copy-ready prompt without every family collapsing into the same two
 * shapes, so these blocks were added.
 *
 * Every field below is optional and every renderer returns null when its block
 * is absent, so the service-and-industry posts written before this existed are
 * unaffected: same DOM, same styles.
 */

/** One ranked provider in a shortlist article. `rank` drives the displayed position. */
export type SilverstoneBlogRankedCard = {
  bestFor?: string;
  limitations?: string;
  name: string;
  rank: number;
  score?: string;
  strengths?: string[];
  summary: string;
  website?: string;
};

/** A deliberately placed entity action; the renderer never guesses from prose. */
export type SilverstoneBlogEntityLink = {
  kind?: "agency" | "platform" | "silverstone" | "source" | "tool";
  name: string;
  url: string;
};

/** Compact editorial recap for readers scanning a long section. */
export type SilverstoneBlogKeyTakeaways = {
  items: string[];
  title?: string;
};

/** A visually dominant evidence band. Values are rendered verbatim. */
export type SilverstoneBlogStatBand = {
  items: {
    detail?: string;
    label: string;
    tone?: "benchmark" | "cost" | "growth" | "time";
    value: string;
  }[];
  title?: string;
};

export type SilverstoneBlogVersusSide = {
  body: string;
  label?: string;
  points?: string[];
  title: string;
};

/** Two explicitly contrasted positions, approaches or products. */
export type SilverstoneBlogVersusCard = {
  eyebrow?: string;
  left: SilverstoneBlogVersusSide;
  right: SilverstoneBlogVersusSide;
  verdict?: string;
};

export type SilverstoneBlogDefinitionList = {
  items: {
    definition: string;
    note?: string;
    term: string;
  }[];
  title?: string;
};

/** A dated or phased sequence; use `steps` when labels are not time-based. */
export type SilverstoneBlogTimeline = {
  items: {
    body: string;
    label?: string;
    title: string;
  }[];
  title?: string;
};

export type SilverstoneBlogQuoteCard = {
  attribution: string;
  quote: string;
  role?: string;
  url?: string;
};

/** A weighted criterion scored across the options named in `options`. */
export type SilverstoneBlogScorecard = {
  options: string[];
  rows: {
    cells: string[];
    criterion: string;
    weight?: string;
  }[];
  totals?: string[];
};

/**
 * A copy-ready prompt. `tone: "weak"` renders the deliberately poor example in a
 * bad-vs-improved pair, so the two are visually distinguishable.
 */
export type SilverstoneBlogPromptBlock = {
  explanation?: string;
  label: string;
  prompt: string;
  tone?: "improved" | "weak";
};

export type SilverstoneBlogChecklist = {
  items: {
    detail?: string;
    label: string;
  }[];
  ordered?: boolean;
  title?: string;
};

/** An ordered implementation, diagnostic or roadmap sequence. */
export type SilverstoneBlogStep = {
  body: string;
  label?: string;
  title: string;
};

/**
 * A framed panel. `answer` renders above the section body so a cost or
 * definition article can lead with its direct answer; every other tone renders
 * after the body.
 */
export type SilverstoneBlogCallout = {
  body: string[];
  label?: string;
  title?: string;
  tone: "answer" | "assumption" | "caution" | "evidence" | "recommendation";
};

/** Figure strip — research dates, budget bands, break-even points. */
export type SilverstoneBlogMetricPanel = {
  items: {
    label: string;
    note?: string;
    value: string;
  }[];
  title?: string;
};

export type SilverstoneBlogSection = {
  body: string[];
  bullets?: SilverstoneBlogBullet[];
  callout?: SilverstoneBlogCallout;
  checklist?: SilverstoneBlogChecklist;
  comparisonTable?: SilverstoneBlogTable;
  definitions?: SilverstoneBlogDefinitionList;
  entityLinks?: SilverstoneBlogEntityLink[];
  grid?: SilverstoneBlogGridItem[];
  heading: string;
  keyTakeaways?: SilverstoneBlogKeyTakeaways;
  leadStyle?: "drop-cap" | "lead";
  lede?: string;
  metricPanel?: SilverstoneBlogMetricPanel;
  promptBlocks?: SilverstoneBlogPromptBlock[];
  pullQuote?: string;
  quoteCard?: SilverstoneBlogQuoteCard;
  rankedCards?: SilverstoneBlogRankedCard[];
  scorecard?: SilverstoneBlogScorecard;
  sectionNumber?: string;
  statBand?: SilverstoneBlogStatBand;
  steps?: SilverstoneBlogStep[];
  subsections?: SilverstoneBlogSection[];
  timeline?: SilverstoneBlogTimeline;
  variant?: "operator" | "signal" | "system";
  versusCard?: SilverstoneBlogVersusCard;
};

/**
 * Which presentation family the search-led branch composed the article from.
 * Carried so the article shell can vary its accent treatment per family and so
 * the automation's design fingerprint stays auditable in the published data.
 */
export type SilverstoneBlogPresentation = {
  ctaPlacement?: string;
  family?: string;
  fingerprint?: string;
};

/**
 * Research citation emitted by the blog automation. Two generations of the
 * automation are represented in the data: the older shape carries `date` and
 * `relevance`, the newer one carries `domain`, `verifiedAt`, `publishedDate`
 * and `matchedTerms`. Every field except `title`/`url` is therefore optional.
 */
export type SilverstoneBlogSource = {
  date?: string;
  domain?: string;
  matchedTerms?: string[];
  publishedDate?: string;
  relevance?: string;
  summary?: string;
  title: string;
  url: string;
  verifiedAt?: string;
  /*
   * Registry-verified provider fields. The `search_led_general_ai` stream
   * emits these on sources it resolved through a provider registry rather than
   * an open web search, so a ranked-shortlist article can record what was
   * verified about each named organisation. They were undeclared here until
   * 2026-08-05, which failed `npm run typecheck` (excess-property errors on
   * every affected source) even though the production build — esbuild, no type
   * checking — shipped happily. Nothing renders them yet; they are provenance.
   */
  organisationName?: string;
  pricingVisibility?: string;
  providerType?: string;
  registryProvider?: boolean;
  smeFit?: string;
  verifiedCapabilities?: string;
};

export type SilverstoneBlogPost = {
  articleBody: SilverstoneBlogSection[];
  /**
   * Visible byline. Optional because every article published before the
   * automation carried one relies on the DEFAULT_BLOG_AUTHOR fallback in the
   * article template, which renders the same organisational byline rather
   * than leaving the back catalogue unattributed.
   */
  author?: string;
  categoryId: string;
  categoryKey: string;
  categoryLabel: string;
  categoryOrder: number;
  ctaPrimary: SilverstoneBlogLink;
  ctaSecondary: SilverstoneBlogLink;
  displayDate: string;
  faqs: SilverstoneBlogFaq[];
  heroImage: string;
  heroImageAlt: string;
  imagePrompt: string;
  internalLinks: SilverstoneBlogLink[];
  /**
   * Which market the article was written for. Optional because the articles
   * published before the dual-market rotation are all UK, and are treated as
   * such wherever this is read.
   */
  market?: "BOTH" | "UK" | "US";
  metaDescription: string;
  metaTitle: string;
  presentation?: SilverstoneBlogPresentation;
  primaryKeyword: string;
  publishedIsoDate: string;
  readTime: string;
  researchSources: SilverstoneBlogSource[];
  secondaryKeywords: string[];
  slug: string;
  status: "draft" | "published";
  subtitle: string;
  summary: string[];
  title: string;
  updatedIsoDate: string;
};

